# %% [markdown]
# ## Step 7 — Automated Metric: ROUGE-L
#
# ROUGE-L measures the longest common subsequence between the reference and generated answer. It's fast and requires no additional API calls.

# %%
def rouge_l(reference, hypothesis):
    """Compute ROUGE-L F1 score (LCS-based recall/precision)."""
    ref_tokens = reference.lower().split()
    hyp_tokens = hypothesis.lower().split()
    
    m, n = len(ref_tokens), len(hyp_tokens)
    if m == 0 or n == 0:
        return 0.0
    
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if ref_tokens[i - 1] == hyp_tokens[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    
    lcs_len = dp[m][n]
    precision = lcs_len / n if n > 0 else 0.0
    recall = lcs_len / m if m > 0 else 0.0
    f1 = (2 * precision * recall) / (precision + recall) if (precision + recall) > 0 else 0.0
    return round(f1, 3)

rouge_v1 = []
rouge_v2 = []

for i in range(len(test_cases)):
    r1 = rouge_l(test_cases[i]["reference"], v1_answers[i])
    r2 = rouge_l(test_cases[i]["reference"], v2_answers[i])
    rouge_v1.append(r1)
    rouge_v2.append(r2)

print("ROUGE-L scores (v1 vs v2):")
for i in range(len(test_cases)):
    print(f"  [{test_cases[i]['id']}] v1={rouge_v1[i]:.3f}  v2={rouge_v2[i]:.3f}")

print()
print(f"Average ROUGE-L: v1={sum(rouge_v1)/len(rouge_v1):.3f}  v2={sum(rouge_v2)/len(rouge_v2):.3f}")

# %% [markdown]
# ## Step 8 — Regression Detection & SHIP/BLOCK Decision
#
# Now we compare v1 (baseline) against v2 (proposed) using the LLM judge scores and ROUGE-L. A regression on **any** criterion blocks the deployment.

# %%
import statistics

def compute_regression(baseline_scores, new_scores):
    """Check if new version shows significant regression."""
    if not baseline_scores or not new_scores:
        return {"regression": False, "reason": "Insufficient data"}
    
    baseline_mean = statistics.mean(baseline_scores)
    new_mean = statistics.mean(new_scores)
    diff = new_mean - baseline_mean
    
    threshold = -0.3  # Regression if diff < -0.3
    
    if diff < threshold:
        return {"regression": True, "reason": f"Significant drop: {baseline_mean:.2f} -> {new_mean:.2f} (diff: {diff:.2f})"}
    else:
        return {"regression": False, "reason": f"Stable or improved: {baseline_mean:.2f} -> {new_mean:.2f} (diff: {diff:+.2f})"}

criteria = ["relevance", "correctness", "helpfulness", "safety"]
regression_results = {}

for criterion in criteria:
    baseline = [s.get(criterion, 3) for s in v1_scores]
    new = [s.get(criterion, 3) for s in v2_scores]
    result = compute_regression(baseline, new)
    regression_results[criterion] = result

print("\n" + "="*60)
print(" EVALUATION RESULTS: v1 (baseline) vs v2 (proposed)")
print("="*60)

any_regression = False
for criterion in criteria:
    result = regression_results[criterion]
    status = "🔴 REGRESSION" if result["regression"] else "✅ STABLE"
    any_regression = any_regression or result["regression"]
    print(f"\n{criterion.upper():15} {status}")
    print(f"  {result['reason']}")

print(f"\nROUGE-L: v1={sum(rouge_v1)/len(rouge_v1):.3f}  v2={sum(rouge_v2)/len(rouge_v2):.3f}")

print("\n" + "="*60)
if any_regression:
    print(" VERDICT: 🛑 BLOCK")
    print(" Action: Do not ship v2. Investigate regressions.")
else:
    print(" VERDICT: ✅ SHIP")
    print(" Action: v2 is ready for production deployment.")
print("="*60)

